macro_rules! due {
    ($stamp:literal, $tries:literal) => {
        concat!(
            $stamp,
            " + ",
            wait!($tries),
            " + ",
            $stamp,
            " % (2 * (",
            wait!($tries),
            " / 4) + 1) - ",
            wait!($tries),
            " / 4 <= json_extract(?1, '$.pace.now_ms')"
        )
    };
}

macro_rules! sparse {
    ($clue:literal) => {
        concat!(
            "(SELECT COUNT(DISTINCT w.conversation_id) FROM clues v JOIN lines w ON w.key = v.key WHERE v.kind = ",
            $clue,
            ".kind AND v.value = ",
            $clue,
            ".value) <= json_extract(?1, '$.max_conversations')"
        )
    };
}

macro_rules! wait {
    ($tries:literal) => {
        concat!(
            "MIN(json_extract(?1, '$.pace.retry_after_ms') << MIN(MAX(",
            $tries,
            " - 1, 0), 20), json_extract(?1, '$.pace.retry_max_ms'))"
        )
    };
}

pub(super) const ADVANCE_ALERT: &str = "UPDATE alerts SET state = json_extract(?1, '$.state'), analysis = COALESCE(json_extract(?1, '$.analysis'), analysis), reason = '', attempts = 0, updated_at_ms = 0, sent_at_ms = CASE WHEN json_extract(?1, '$.state') = 'sent' THEN json_extract(?1, '$.at_ms') ELSE sent_at_ms END WHERE key = json_extract(?1, '$.key') AND state = json_extract(?1, '$.from')";
pub(super) const ALIAS_CHAIN: &str = "UPDATE topic_aliases SET new = json_extract(?1, '$.thread_id') WHERE new = json_extract(?1, '$.topic_id') AND json_extract(?1, '$.topic_id') <> json_extract(?1, '$.thread_id')";
pub(super) const ALIAS_TOPIC: &str = "INSERT OR REPLACE INTO topic_aliases (old, new) SELECT json_extract(?1, '$.topic_id'), json_extract(?1, '$.thread_id') WHERE json_extract(?1, '$.topic_id') <> json_extract(?1, '$.thread_id') AND EXISTS (SELECT 1 FROM topics WHERE id = json_extract(?1, '$.thread_id'))";
pub(super) const ANSWER: &str = "INSERT OR REPLACE INTO answers (batch_id, body) VALUES (json_extract(?1, '$.batch_id'), json_extract(?1, '$.body'))";
pub(super) const ARCHIVE: &str = "UPDATE topics SET state = 'archived' WHERE state <> 'archived' AND last_at_ms < json_extract(?1, '$.before_ms')";
pub(super) const ATTACH: &str = "SELECT json_group_array(json_object('conversation_id', conversation_id, 'last_ms', last_ms, 'probability', probability, 'topic_id', topic_id)) FROM (SELECT l.conversation_id AS conversation_id, MAX(l.occurred_at_ms) AS last_ms, t.probability AS probability, p.topic_id AS topic_id FROM members p JOIN lines l ON l.key = p.key JOIN topics t ON t.id = p.topic_id WHERE l.conversation_id IN (SELECT conversation_id FROM lines WHERE batch_id = json_extract(?1, '$.batch_id')) GROUP BY l.conversation_id)";
pub(super) const BACKLOG: &str = "SELECT json_group_array(json_object('attempts', a.attempts, 'created_at_ms', a.created_at_ms, 'key', a.key, 'label', t.label, 'score', COALESCE(t.score, a.score), 'state', t.state)) FROM (SELECT * FROM alerts WHERE state = 'analyzed' AND attempts = 0 AND json_extract(?1, '$') IS NULL ORDER BY created_at_ms, key) a JOIN topics t ON t.id = a.topic_id";
pub(super) const BATCH_CALL_RELEASE: &str = "DELETE FROM calls WHERE kind = 'decision' AND subject = CAST(json_extract(?1, '$.id') AS TEXT) AND attempt = (SELECT attempts FROM batches WHERE id = json_extract(?1, '$.id'))";
pub(super) const BATCH_CLAIM: &str = "UPDATE batches SET attempts = attempts + 1, payload = json_extract(?1, '$.payload'), layout = json_extract(?1, '$.layout'), version = json_extract(?1, '$.version'), updated_at_ms = json_extract(?1, '$.at_ms') WHERE id = json_extract(?1, '$.id') AND state = 'ready' AND attempts < json_extract(?1, '$.max_attempts') * (revivals + 1) AND NOT EXISTS (SELECT 1 FROM learned_rules WHERE id > json_extract(?1, '$.rev'))";
pub(super) const BATCH_FAIL: &str = "UPDATE batches SET reason = json_extract(?1, '$.reason'), updated_at_ms = json_extract(?1, '$.at_ms'), state = CASE WHEN attempts >= json_extract(?1, '$.max_attempts') * (revivals + 1) THEN 'failed' ELSE state END WHERE id = json_extract(?1, '$.id') AND state = 'ready'";
pub(super) const BATCH_LINES: &str = "SELECT json_group_array(json_object('conversation_id', conversation_id, 'created_at_ms', created_at_ms, 'digest', digest, 'hints', json((SELECT json_group_array(COALESCE((SELECT new FROM topic_aliases WHERE old = h.value), h.value)) FROM json_each(b.hints) h)), 'key', key, 'occurred_at_ms', occurred_at_ms, 'role', role, 'sender', sender, 'text', text)) FROM (SELECT * FROM lines WHERE batch_id = json_extract(?1, '$.batch_id') AND state = 'approved' ORDER BY occurred_at_ms, key) b";
pub(super) const BATCH_NEXT: &str = concat!(
    "SELECT json_group_array(json_object('answer', answer, 'attempts', attempts, 'id', id, 'layout', layout, 'payload', payload, 'revivals', revivals)) FROM (SELECT a.body AS answer, b.attempts AS attempts, b.id AS id, b.layout AS layout, b.payload AS payload, b.revivals AS revivals FROM batches b LEFT JOIN answers a ON a.batch_id = b.id WHERE b.state = 'ready' AND ",
    due!("b.updated_at_ms", "b.attempts"),
    " AND (a.body IS NOT NULL OR b.attempts < json_extract(?1, '$.max_attempts') * (b.revivals + 1)) ORDER BY b.id LIMIT 1)"
);
pub(super) const BATCH_RELEASE: &str = "UPDATE batches SET attempts = attempts - 1, updated_at_ms = 0 WHERE id = json_extract(?1, '$.id') AND state = 'ready' AND attempts > 0";
pub(super) const BATCH_SEAL: &str = "INSERT OR IGNORE INTO batches (id, state, payload, layout, attempts, reason, created_at_ms, updated_at_ms) SELECT json_extract(?1, '$.id'), json_extract(?1, '$.state'), json_extract(?1, '$.payload'), json_extract(?1, '$.layout'), 0, '', json_extract(?1, '$.at_ms'), json_extract(?1, '$.updated_ms') WHERE json_extract(?1, '$.state') <> 'ready' OR NOT EXISTS (SELECT 1 FROM batches WHERE state = 'ready')";
pub(super) const BATCH_SENT: &str = "UPDATE batches SET state = 'sent', attempts = 0, reason = '', updated_at_ms = json_extract(?1, '$.at_ms') WHERE id = json_extract(?1, '$.batch_id') AND state = 'ready'";
pub(super) const BEGIN: &str = "BEGIN IMMEDIATE";
pub(super) const BIND_THREAD: &str = "UPDATE topics SET thread_id = json_extract(?1, '$.thread_id'), thread_at_ms = CASE WHEN thread_at_ms = 0 THEN json_extract(?1, '$.at_ms') ELSE thread_at_ms END WHERE id = json_extract(?1, '$.thread_id')";
pub(super) const CALL_ALERT: &str = "INSERT INTO calls (kind, subject, topic_id, attempt, at_ms, version) SELECT json_extract(?1, '$.kind'), key, topic_id, attempts, json_extract(?1, '$.at_ms'), COALESCE(json_extract(?1, '$.version'), '') FROM alerts WHERE key = json_extract(?1, '$.key') AND updated_at_ms = json_extract(?1, '$.at_ms')";
pub(super) const CALL_BATCH: &str = "INSERT INTO calls (kind, subject, topic_id, attempt, at_ms, version) SELECT 'decision', CAST(id AS TEXT), '', attempts, json_extract(?1, '$.at_ms'), json_extract(?1, '$.version') FROM batches WHERE id = json_extract(?1, '$.id') AND updated_at_ms = json_extract(?1, '$.at_ms')";
pub(super) const CHANGES: &str = "SELECT json_group_array(json_object('from', from_topic, 'id', id, 'into', to_topic, 'keys', json(keys), 'kind', kind)) FROM (SELECT * FROM changes WHERE state = 'pending' AND json_extract(?1, '$') IS NULL ORDER BY id LIMIT 32)";
const CHANGE_CLAIM: &str = "UPDATE changes SET state = 'applied', to_topic = json_extract(?1, '$.to'), at_ms = json_extract(?1, '$.at_ms') WHERE id = json_extract(?1, '$.id') AND state = 'pending' AND NOT EXISTS (SELECT 1 FROM alerts f WHERE f.topic_id IN (json_extract(?1, '$.from'), json_extract(?1, '$.to')) AND f.state = 'pending' AND f.attempts > 0 AND f.analysis IS NULL)";
const CHANGE_DROP: &str = "UPDATE changes SET state = 'dropped', at_ms = json_extract(?1, '$.at_ms') WHERE id = json_extract(?1, '$.id') AND state = 'pending' AND (NOT EXISTS (SELECT 1 FROM topics WHERE id = json_extract(?1, '$.from')) OR (json_extract(?1, '$.kind') <> 'split' AND NOT EXISTS (SELECT 1 FROM topics WHERE id = json_extract(?1, '$.to'))))";
pub(super) const CLAIM_ALERT: &str = "UPDATE alerts SET attempts = attempts + 1, updated_at_ms = json_extract(?1, '$.at_ms') WHERE key = json_extract(?1, '$.key') AND state = json_extract(?1, '$.state') AND attempts < json_extract(?1, '$.max_attempts') AND created_at_ms = json_extract(?1, '$.created_at_ms')";
pub(super) const CLAIM_REMINDER: &str = "INSERT INTO reminders (key, state, attempts, updated_at_ms) VALUES (json_extract(?1, '$.key'), 'pending', 1, json_extract(?1, '$.at_ms')) ON CONFLICT(key) DO UPDATE SET attempts = attempts + 1, updated_at_ms = excluded.updated_at_ms WHERE reminders.state <> 'sent' AND reminders.attempts < json_extract(?1, '$.max_attempts')";
pub(super) const CLUES: &str = "INSERT OR IGNORE INTO clues (kind, value, key, occurred_at_ms) SELECT json_extract(value, '$.kind'), json_extract(value, '$.value'), json_extract(?1, '$.key'), json_extract(?1, '$.occurred_at_ms') FROM json_each(?1, '$.clues') UNION ALL SELECT 'seen', json_extract(?1, '$.key'), json_extract(?1, '$.key'), json_extract(?1, '$.occurred_at_ms') UNION ALL SELECT 'digest', digest, key, occurred_at_ms FROM lines WHERE key = json_extract(?1, '$.key') AND digest <> ''";
pub(super) const COLLAPSE_ALERTS: &str = "UPDATE alerts SET state = 'merged', merged_into = topic_id WHERE state = 'pending' AND analysis IS NULL AND json_extract(?1, '$') IS NULL AND EXISTS (SELECT 1 FROM alerts n WHERE n.topic_id = alerts.topic_id AND n.state = 'pending' AND n.analysis IS NULL AND (n.created_at_ms, n.key) > (alerts.created_at_ms, alerts.key))";
pub(super) const COMMIT: &str = "COMMIT";
pub(super) const DEFER: &str = "UPDATE lines SET attempts = attempts + 1, reason = 'deferred', updated_at_ms = json_extract(?1, '$.at_ms') WHERE state = 'screening' AND key IN (SELECT value FROM json_each(?1, '$.keys'))";
pub(super) const DOOMED_THREADS: &str = "SELECT json_group_array(json_object('thread_id', thread_id, 'topic_id', id)) FROM (SELECT t.id AS id, h.id AS thread_id FROM threads h JOIN topics t ON t.id = COALESCE((SELECT new FROM topic_aliases WHERE old = h.topic_id), h.topic_id) WHERE h.purged_at_ms = 0 AND t.state = 'archived' AND t.last_at_ms < json_extract(?1, '$.before_ms') AND NOT EXISTS (SELECT 1 FROM members p JOIN messages m ON m.key = p.key WHERE p.topic_id = t.id AND m.purged_at_ms = 0) ORDER BY h.id LIMIT json_extract(?1, '$.limit'))";
pub(super) const DRIFT: &str = "SELECT json_group_array(json_object('from', from_topic, 'into', to_topic, 'keys', json(keys), 'kind', kind, 'reason', reason, 'size', size)) FROM (SELECT * FROM (SELECT 'clue' AS kind, x.later AS from_topic, x.earlier AS to_topic, json_group_array(DISTINCT x.key) AS keys, (SELECT COUNT(*) FROM members s JOIN lines q ON q.key = s.key WHERE s.topic_id = x.later AND q.state = 'approved') AS size, group_concat(DISTINCT x.kind) AS reason FROM (SELECT ma.topic_id AS later, mb.topic_id AS earlier, ca.key AS key, ca.kind AS kind FROM clues ca JOIN clues cb ON cb.kind = ca.kind AND cb.value = ca.value AND cb.key <> ca.key JOIN members ma ON ma.key = ca.key JOIN members mb ON mb.key = cb.key JOIN topics ta ON ta.id = ma.topic_id JOIN topics tb ON tb.id = mb.topic_id WHERE ca.kind IN ('digest', 'mail') AND ma.topic_id <> mb.topic_id AND (ta.created_at_ms, ta.id) > (tb.created_at_ms, tb.id) AND NOT EXISTS (SELECT 1 FROM members z WHERE z.key = ca.key AND z.topic_id = mb.topic_id) AND NOT EXISTS (SELECT 1 FROM members z WHERE z.key = cb.key AND z.topic_id = ma.topic_id)) x GROUP BY x.later, x.earlier UNION ALL SELECT 'vote', CASE WHEN (ta.created_at_ms, ta.id) > (tb.created_at_ms, tb.id) THEN ta.id ELSE tb.id END, CASE WHEN (ta.created_at_ms, ta.id) > (tb.created_at_ms, tb.id) THEN tb.id ELSE ta.id END, '[]', 0, 'vote' FROM relations r JOIN topics ta ON ta.id = r.a JOIN topics tb ON tb.id = r.b WHERE r.kind = 'maybe' AND r.count >= json_extract(?1, '$.merge_after') AND r.a <> r.b UNION ALL SELECT 'apart', r.b, '', (SELECT json_group_array(s.key) FROM members s JOIN lines q ON q.key = s.key WHERE s.topic_id = r.b AND q.conversation_id = l.conversation_id), (SELECT COUNT(*) FROM members s WHERE s.topic_id = r.b), 'apart' FROM relations r JOIN lines l ON l.key = r.a JOIN members m ON m.key = r.a AND m.topic_id = r.b WHERE r.kind = 'apart' AND r.count >= json_extract(?1, '$.split_after')) y WHERE NOT EXISTS (SELECT 1 FROM changes c WHERE c.state = 'pending' AND (c.from_topic IN (y.from_topic, y.to_topic) OR (c.to_topic <> '' AND c.to_topic IN (y.from_topic, y.to_topic)))) ORDER BY y.kind, y.from_topic, y.to_topic)";
pub(super) const FAIL_ALERT: &str = "UPDATE alerts SET reason = json_extract(?1, '$.reason'), updated_at_ms = json_extract(?1, '$.at_ms'), state = CASE WHEN attempts >= json_extract(?1, '$.max_attempts') THEN 'failed' ELSE state END WHERE key = json_extract(?1, '$.key') AND state = json_extract(?1, '$.state')";
pub(super) const FORGET_PURGED: &str = "UPDATE topics SET thread_at_ms = 0, purged_at_ms = json_extract(?1, '$.at_ms') WHERE id = json_extract(?1, '$.topic_id')";
pub(super) const FORGET_SESSION: &str = "UPDATE threads SET purged_at_ms = json_extract(?1, '$.at_ms') WHERE id = json_extract(?1, '$.thread_id')";
pub(super) const FORGET_THREAD: &str =
    "UPDATE topics SET thread_at_ms = 0 WHERE id = json_extract(?1, '$.topic_id')";
pub(super) const FORM: &str = "UPDATE lines SET batch_id = MAX(COALESCE((SELECT MAX(batch_id) FROM lines), 0), COALESCE((SELECT MAX(id) FROM batches), 0)) + 1, state = json_extract(?1, '$.state'), reviewer = json_extract(?1, '$.reviewer'), updated_at_ms = json_extract(?1, '$.at_ms') WHERE key IN (SELECT key FROM lines WHERE state = 'queued' ORDER BY occurred_at_ms, key LIMIT json_extract(?1, '$.limit')) AND NOT EXISTS (SELECT 1 FROM lines a WHERE a.batch_id > 0 AND NOT EXISTS (SELECT 1 FROM batches b WHERE b.id = a.batch_id))";
pub(super) const IDENTIFY: &str = "INSERT OR REPLACE INTO identities (source, sender_id, person_id, name) SELECT json_extract(value, '$.source'), json_extract(value, '$.sender_id'), json_extract(value, '$.person_id'), json_extract(value, '$.name') FROM json_each(?1, '$.identities')";
pub(super) const INTAKE_SINCE: &str = "SELECT json_group_array(json_object('since_ms', since_ms)) FROM triage_state WHERE id = 1 AND json_extract(?1, '$.enabled') IS NOT NULL";
pub(super) const INTAKE_STATE: &str = "INSERT INTO triage_state (id, enabled, since_ms) VALUES (1, json_extract(?1, '$.enabled'), json_extract(?1, '$.since_ms')) ON CONFLICT(id) DO UPDATE SET since_ms = CASE WHEN triage_state.since_ms = 0 THEN excluded.since_ms ELSE triage_state.since_ms END, enabled = excluded.enabled";
pub(super) const LINKED: &str = concat!(
    "WITH hits AS (SELECT DISTINCT c.key AS key, m.topic_id AS topic, c.kind IN ('digest', 'mail') AS strong FROM lines l JOIN clues c ON c.key = l.key JOIN clues o ON o.kind = c.kind AND o.value = c.value AND o.key <> c.key JOIN members m ON m.key = o.key JOIN topics t ON t.id = m.topic_id WHERE l.batch_id = json_extract(?1, '$.batch_id') AND l.state = 'approved' AND c.kind <> 'seen' AND (c.kind IN ('digest', 'mail') OR (t.state <> 'archived' AND ",
    sparse!("c"),
    "))) SELECT json_group_array(json_object('key', key, 'topic', topic)) FROM (SELECT DISTINCT key, topic FROM hits h WHERE strong OR (SELECT COUNT(DISTINCT g.topic) FROM hits g WHERE g.key = h.key AND NOT g.strong) = 1 ORDER BY key, topic)"
);
pub(super) const MEMBERS: &str = "INSERT OR IGNORE INTO members (key, topic_id, probability, batch_id, via, created_at_ms) SELECT json_extract(value, '$.key'), COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(value, '$.topic')), json_extract(value, '$.topic')), json_extract(value, '$.probability'), json_extract(?1, '$.batch_id'), json_extract(value, '$.via'), json_extract(?1, '$.at_ms') FROM json_each(?1, '$.placements') WHERE json_extract(value, '$.topic') IS NOT NULL";
pub(super) const MERGE_ALERT: &str = "UPDATE alerts SET created_at_ms = json_extract(?1, '$.at_ms'), score = MAX(COALESCE(score, 0), COALESCE((SELECT t.score FROM topics t WHERE t.id = alerts.topic_id), 0)) WHERE topic_id = COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(?1, '$.topic_id')), json_extract(?1, '$.topic_id')) AND state IN ('waiting', 'pending') AND analysis IS NULL AND attempts = 0";
pub(super) const MIGRATE: &str = "BEGIN IMMEDIATE; UPDATE topic_aliases SET new = (SELECT t.thread_id FROM topics t WHERE t.id = topic_aliases.new) WHERE EXISTS (SELECT 1 FROM topics t WHERE t.id = topic_aliases.new AND t.id <> t.thread_id AND t.thread_id <> ''); INSERT OR REPLACE INTO topic_aliases (old, new) SELECT id, thread_id FROM topics WHERE id <> thread_id AND thread_id <> ''; INSERT INTO topics (id, label, probability, thread_id, until_ms, until_key, thread_at_ms, created_at_ms, last_at_ms) SELECT thread_id, label, probability, thread_id, until_ms, until_key, thread_at_ms, created_at_ms, last_at_ms FROM topics WHERE id <> thread_id AND thread_id <> ''; UPDATE placements SET topic_id = (SELECT t.thread_id FROM topics t WHERE t.id = placements.topic_id) WHERE EXISTS (SELECT 1 FROM topics t WHERE t.id = placements.topic_id AND t.id <> t.thread_id AND t.thread_id <> ''); UPDATE alerts SET topic_id = (SELECT t.thread_id FROM topics t WHERE t.id = alerts.topic_id) WHERE EXISTS (SELECT 1 FROM topics t WHERE t.id = alerts.topic_id AND t.id <> t.thread_id AND t.thread_id <> ''); UPDATE calls SET topic_id = (SELECT t.thread_id FROM topics t WHERE t.id = calls.topic_id) WHERE EXISTS (SELECT 1 FROM topics t WHERE t.id = calls.topic_id AND t.id <> t.thread_id AND t.thread_id <> ''); DELETE FROM topics WHERE id <> thread_id AND thread_id <> ''; DELETE FROM lines WHERE state = 'skipped' AND reason IN ('own', 'expired'); UPDATE lines SET state = 'queued', batch_id = 0, reviewer = '' WHERE state IN ('pending', 'leaked'); UPDATE lines SET state = 'withheld' WHERE state = 'skipped' AND reason IN ('sealed', 'empty'); UPDATE lines SET state = 'withheld', reason = CASE WHEN flag = 'unmasked' THEN 'risky' ELSE 'unscreened' END WHERE state = 'rejected' AND reason = 'screen'; INSERT OR IGNORE INTO members (key, topic_id, probability, batch_id, via, created_at_ms) SELECT key, topic_id, probability, batch_id, 'legacy', 0 FROM placements WHERE NOT EXISTS (SELECT 1 FROM members x WHERE x.key = placements.key); UPDATE topics SET urgency = probability, score = probability WHERE score IS NULL AND probability IS NOT NULL; UPDATE messages SET conversation_id = 'mail:' || account || ':thread:' || COALESCE(json_extract(raw, '$.references[0]'), json_extract(raw, '$.in_reply_to'), json_extract(raw, '$.message_id'), substr(key, length(source) + length(account) + 3)) WHERE conversation_id LIKE 'mail:%' AND substr(conversation_id, 1, length(account) + 13) <> 'mail:' || account || ':thread:' AND json_valid(raw); UPDATE lines SET conversation_id = (SELECT m.conversation_id FROM messages m WHERE m.key = lines.key) WHERE conversation_id LIKE 'mail:%' AND EXISTS (SELECT 1 FROM messages m WHERE m.key = lines.key AND m.conversation_id <> lines.conversation_id); DELETE FROM answers WHERE body = '{\"answers\":[]}' AND batch_id IN (SELECT id FROM batches WHERE state = 'ready'); INSERT OR IGNORE INTO threads (id, topic_id, purged_at_ms) SELECT thread_id, id, purged_at_ms FROM topics WHERE thread_id <> ''; INSERT OR IGNORE INTO threads (id, topic_id) SELECT old, new FROM topic_aliases WHERE old NOT GLOB 't[0-9]*-[0-9]*' AND old NOT GLOB 's[0-9]*'; COMMIT;";
pub(super) const MISS: &str = "INSERT INTO misses (kind, key, text, spans, created_at_ms) SELECT json_extract(?1, '$.kind'), key, text, json_extract(?1, '$.spans'), json_extract(?1, '$.at_ms') FROM lines WHERE key = json_extract(?1, '$.key') AND state = 'screening' AND json_extract(?1, '$.kind') <> ''";
pub(super) const NEXT_ALERT: &str = concat!(
    "SELECT json_group_array(json_object('analysis', analysis, 'attempts', attempts, 'changes', changes, 'created_at_ms', created_at_ms, 'key', key, 'label', label, 'last_at_ms', last_at_ms, 'origin', origin, 'reach', json(reach), 'score', score, 'state', state, 'studied', studied, 'thread_at_ms', thread_at_ms, 'thread_id', thread_id, 'topic_id', topic_id, 'urgency', urgency)) FROM (SELECT a.analysis AS analysis, t.digest AS studied, a.attempts AS attempts, a.changes AS changes, a.created_at_ms AS created_at_ms, a.key AS key, t.label AS label, t.last_at_ms AS last_at_ms, a.origin AS origin, t.reach AS reach, COALESCE(t.score, a.score, t.probability) AS score, t.state AS state, t.thread_at_ms AS thread_at_ms, t.thread_id AS thread_id, a.topic_id AS topic_id, t.urgency AS urgency FROM alerts a JOIN topics t ON t.id = a.topic_id WHERE a.state = json_extract(?1, '$.state') AND ",
    due!("a.updated_at_ms", "a.attempts"),
    " AND (a.attempts < json_extract(?1, '$.max_attempts') OR (a.state = 'pending' AND a.analysis IS NOT NULL)) AND (a.state <> 'analyzed' OR NOT EXISTS (SELECT 1 FROM alerts s WHERE s.topic_id = a.topic_id AND s.state = 'sent' AND s.sent_at_ms > json_extract(?1, '$.pace.now_ms') - json_extract(?1, '$.cooldown_ms'))) ORDER BY COALESCE(t.score, a.score, 0) DESC, a.created_at_ms, a.key LIMIT json_extract(?1, '$.parallel'))"
);
pub(super) const NOTE_CALL: &str = "INSERT OR REPLACE INTO calls (kind, subject, topic_id, attempt, at_ms, state, input_tokens, output_tokens, version) VALUES (json_extract(?1, '$.kind'), json_extract(?1, '$.key'), '', json_extract(?1, '$.attempt'), json_extract(?1, '$.at_ms'), json_extract(?1, '$.state'), 0, 0, '')";
pub(super) const NOTE_THREAD: &str = "INSERT OR IGNORE INTO threads (id, topic_id) VALUES (json_extract(?1, '$.thread_id'), json_extract(?1, '$.topic_id'))";
pub(super) const NOTICE_SUPERSEDE: &str = "UPDATE alerts SET state = 'merged', merged_into = topic_id WHERE state = 'analyzed' AND json_extract(?1, '$') IS NULL AND EXISTS (SELECT 1 FROM alerts n WHERE n.topic_id = alerts.topic_id AND n.state = 'analyzed' AND (n.created_at_ms, n.key) > (alerts.created_at_ms, alerts.key))";
pub(super) const OPEN_ALERT: &str = "INSERT OR IGNORE INTO alerts (key, topic_id, state, attempts, analysis, reason, created_at_ms, updated_at_ms, score) SELECT json_extract(?1, '$.key'), t.id, 'waiting', 0, NULL, '', json_extract(?1, '$.at_ms'), 0, t.score FROM topics t WHERE t.id = COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(?1, '$.topic_id')), json_extract(?1, '$.topic_id')) AND (t.score >= json_extract(?1, '$.threshold') OR t.thread_id <> '') AND NOT EXISTS (SELECT 1 FROM alerts WHERE topic_id = t.id AND state IN ('waiting', 'pending') AND analysis IS NULL AND attempts = 0)";
pub(super) const OPEN_LINE: &str = "INSERT OR IGNORE INTO lines (key, conversation_id, occurred_at_ms, sender, text, state, reason, reviewer, flag, hints, rules_rev, batch_id, created_at_ms, updated_at_ms, role, digest) VALUES (json_extract(?1, '$.key'), json_extract(?1, '$.conversation_id'), json_extract(?1, '$.occurred_at_ms'), json_extract(?1, '$.sender'), json_extract(?1, '$.text'), json_extract(?1, '$.state'), json_extract(?1, '$.reason'), '', '', '[]', json_extract(?1, '$.rules_rev'), 0, json_extract(?1, '$.at_ms'), json_extract(?1, '$.at_ms'), json_extract(?1, '$.role'), json_extract(?1, '$.digest'))";
pub(super) const OPEN_TOPICS: &str = "SELECT json_group_array(json_object('created_at_ms', created_at_ms, 'first', (SELECT l.text FROM members p JOIN lines l ON l.key = p.key WHERE p.topic_id = t.id AND l.state = 'approved' ORDER BY l.occurred_at_ms, l.key LIMIT 1), 'label', label, 'probability', probability, 'topic', id)) FROM (SELECT id, label, probability, created_at_ms FROM topics WHERE state <> 'archived' ORDER BY last_at_ms DESC, id LIMIT json_extract(?1, '$.limit')) t";
pub(super) const PLACE_WITHHELD: &str = "INSERT OR IGNORE INTO members (key, topic_id, probability, batch_id, via, created_at_ms) SELECT w.key, p.topic_id, NULL, p.batch_id, 'neighbour', json_extract(?1, '$.at_ms') FROM lines w JOIN members p ON p.key = (SELECT l.key FROM lines l WHERE l.conversation_id = w.conversation_id AND l.occurred_at_ms BETWEEN w.occurred_at_ms - json_extract(?1, '$.gap_ms') AND w.occurred_at_ms + json_extract(?1, '$.gap_ms') AND EXISTS (SELECT 1 FROM members x WHERE x.key = l.key) ORDER BY ABS(l.occurred_at_ms - w.occurred_at_ms), l.key LIMIT 1) WHERE w.state = 'withheld' AND NOT EXISTS (SELECT 1 FROM members x WHERE x.key = w.key)";
pub(super) const PROPOSE: &str = "INSERT INTO changes (kind, from_topic, to_topic, keys, reason, state, at_ms) SELECT json_extract(value, '$.kind'), json_extract(value, '$.from'), json_extract(value, '$.into'), json_extract(value, '$.keys'), json_extract(value, '$.reason'), 'pending', json_extract(?1, '$.at_ms') FROM json_each(?1, '$.changes')";
pub(super) static PURGE: [(&str, bool); 10] = [
    (PURGE_TABLE, false),
    (PURGE_CLEAR, false),
    (PURGE_PICK, true),
    (PURGE_MESSAGES, true),
    (PURGE_LINES, false),
    (PURGE_MISSES, false),
    (PURGE_CLUES, false),
    (PURGE_BATCHES, true),
    (PURGE_ANSWERS, true),
    (PURGE_CLEAR, false),
];
pub(super) const PURGE_ANSWERS: &str = "DELETE FROM answers WHERE batch_id IN (SELECT id FROM batches WHERE state = 'sent' AND created_at_ms < json_extract(?1, '$.before_ms'))";
pub(super) const PURGE_BATCHES: &str = "UPDATE batches SET payload = '', layout = '' WHERE state = 'sent' AND created_at_ms < json_extract(?1, '$.before_ms') AND payload <> ''";
pub(super) const PURGE_CLEAR: &str = "DELETE FROM doomed";
pub(super) const PURGE_CLUES: &str = "DELETE FROM clues WHERE key IN (SELECT key FROM doomed) AND kind NOT IN ('mail', 'digest', 'seen')";
pub(super) const PURGE_LINES: &str =
    "UPDATE lines SET text = '' WHERE key IN (SELECT key FROM doomed)";
pub(super) const PURGE_MESSAGES: &str = "UPDATE messages SET text = '', raw = '', purged_at_ms = json_extract(?1, '$.at_ms') WHERE key IN (SELECT key FROM doomed)";
pub(super) const PURGE_MISSES: &str =
    "UPDATE misses SET text = '', spans = '[]' WHERE key IN (SELECT key FROM doomed)";
pub(super) const PURGE_PICK: &str = "INSERT INTO doomed (key) SELECT m.key FROM messages m WHERE m.purged_at_ms = 0 AND m.occurred_at_ms < json_extract(?1, '$.before_ms') AND NOT EXISTS (SELECT 1 FROM members p JOIN topics t ON t.id = p.topic_id WHERE p.key = m.key AND t.state <> 'archived') AND NOT EXISTS (SELECT 1 FROM lines l LEFT JOIN batches b ON b.id = l.batch_id WHERE l.key = m.key AND (l.state IN ('queued', 'screening') OR (l.state = 'approved' AND COALESCE(b.state, '') <> 'sent'))) ORDER BY m.occurred_at_ms LIMIT json_extract(?1, '$.limit')";
pub(super) const PURGE_TABLE: &str =
    "CREATE TEMP TABLE IF NOT EXISTS doomed (key TEXT PRIMARY KEY NOT NULL) WITHOUT ROWID";
pub(super) const REACH: &str = "UPDATE topics SET urgency = (SELECT m.probability FROM members m JOIN lines l ON l.key = m.key WHERE m.topic_id = topics.id AND m.probability IS NOT NULL ORDER BY l.occurred_at_ms DESC, l.key DESC LIMIT 1), reach = (SELECT json_object('conversations', COUNT(DISTINCT CASE WHEN copy THEN NULL ELSE conversation_id END), 'people', COUNT(DISTINCT CASE WHEN copy THEN NULL ELSE person END), 'sources', COUNT(DISTINCT source)) FROM (SELECT l.conversation_id AS conversation_id, g.source AS source, CASE WHEN l.role = '' AND l.state <> 'withheld' THEN COALESCE(i.person_id, g.source || ':' || g.sender_id, l.sender) END AS person, l.digest <> '' AND EXISTS (SELECT 1 FROM members d JOIN lines e ON e.key = d.key WHERE d.topic_id = m.topic_id AND e.digest = l.digest AND (e.occurred_at_ms, e.key) < (l.occurred_at_ms, l.key)) AS copy FROM members m JOIN lines l ON l.key = m.key LEFT JOIN messages g ON g.key = m.key LEFT JOIN identities i ON i.source = g.source AND i.sender_id = g.sender_id WHERE m.topic_id = topics.id)) WHERE id IN (SELECT topic_id FROM members WHERE created_at_ms = json_extract(?1, '$.at_ms'))";
pub(super) const RECORD_ANALYSIS: &str = "UPDATE alerts SET analysis = json_extract(?1, '$.analysis'), changes = json_extract(?1, '$.changes'), reason = '', updated_at_ms = 0 WHERE key = json_extract(?1, '$.key') AND state = 'pending'";
pub(super) const RELATE: &str = "INSERT INTO relations (a, b, kind, count) SELECT json_extract(value, '$.fresh'), COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(value, '$.known')), json_extract(value, '$.known')), 'maybe', 1 FROM json_each(?1, '$.relations') WHERE true ON CONFLICT(a, b, kind) DO UPDATE SET count = count + 1";
pub(super) const RELEASE_ALERT: &str = "UPDATE alerts SET attempts = attempts - 1, updated_at_ms = 0 WHERE key = json_extract(?1, '$.key') AND state = json_extract(?1, '$.state') AND attempts > 0";
pub(super) const RELEASE_CALL_ALERT: &str = "DELETE FROM calls WHERE kind = json_extract(?1, '$.kind') AND subject = json_extract(?1, '$.key') AND attempt = (SELECT attempts FROM alerts WHERE key = json_extract(?1, '$.key'))";
pub(super) const RELEASE_REMINDER: &str = "UPDATE reminders SET attempts = attempts - 1, updated_at_ms = 0 WHERE key = json_extract(?1, '$.key') AND state <> 'sent' AND attempts > 0";
pub(super) const REMINDERS: &str = concat!(
    "SELECT json_group_array(json_object('account', c.account, 'attempts', COALESCE(r.attempts, 0), 'key', c.key, 'kind', c.kind, 'since_ms', c.since_ms, 'source', c.source, 'state', c.state, 'streak', c.streak, 'tokens', c.tokens)) FROM (SELECT 'down:' || h.source || ':' || h.account || ':' || h.down_at_ms AS key, 'down' AS kind, h.source AS source, h.account AS account, h.state AS state, h.streak AS streak, h.down_at_ms AS since_ms, 0 AS tokens FROM source_health h WHERE h.state <> 'ok' AND h.down_at_ms > 0 AND h.down_at_ms <= json_extract(?1, '$.pace.now_ms') - json_extract(?1, '$.down_after_ms') AND json_extract(?1, '$.started_ms') <= json_extract(?1, '$.pace.now_ms') - json_extract(?1, '$.down_after_ms') UNION ALL SELECT 'up:' || h.source || ':' || h.account || ':' || h.down_at_ms, 'up', h.source, h.account, h.state, h.streak, h.ok_at_ms, 0 FROM source_health h WHERE h.state = 'ok' AND EXISTS (SELECT 1 FROM reminders d WHERE d.key = 'down:' || h.source || ':' || h.account || ':' || h.down_at_ms AND d.state = 'sent') UNION ALL SELECT 'budget:' || date(json_extract(?1, '$.pace.now_ms') / 1000, 'unixepoch'), 'budget', '', '', '', 0, 0, spent FROM (SELECT SUM(input_tokens + output_tokens) AS spent FROM calls WHERE at_ms >= json_extract(?1, '$.pace.now_ms') / 86400000 * 86400000) WHERE json_extract(?1, '$.daily_tokens') > 0 AND spent > json_extract(?1, '$.daily_tokens')) c LEFT JOIN reminders r ON r.key = c.key WHERE r.key IS NULL OR (r.state <> 'sent' AND r.attempts < json_extract(?1, '$.max_attempts') AND ",
    due!("r.updated_at_ms", "r.attempts"),
    ")"
);
pub(super) const RENAME_ALERTS: &str = "UPDATE alerts SET topic_id = json_extract(?1, '$.thread_id') WHERE topic_id = json_extract(?1, '$.topic_id')";
pub(super) const RENAME_CALLS: &str = "UPDATE calls SET topic_id = json_extract(?1, '$.thread_id') WHERE topic_id = json_extract(?1, '$.topic_id')";
pub(super) const RENAME_CHANGES_FROM: &str = "UPDATE changes SET from_topic = json_extract(?1, '$.thread_id') WHERE from_topic = json_extract(?1, '$.topic_id') AND state = 'pending'";
pub(super) const RENAME_CHANGES_TO: &str = "UPDATE changes SET to_topic = json_extract(?1, '$.thread_id') WHERE to_topic = json_extract(?1, '$.topic_id') AND state = 'pending'";
pub(super) const RENAME_DELETE: &str = "DELETE FROM topics WHERE id = json_extract(?1, '$.topic_id') AND id <> json_extract(?1, '$.thread_id')";
pub(super) const RENAME_MEMBERS: &str = "UPDATE OR IGNORE members SET topic_id = json_extract(?1, '$.thread_id') WHERE topic_id = json_extract(?1, '$.topic_id')";
pub(super) const RENAME_RELATIONS_A: &str = "UPDATE OR IGNORE relations SET a = json_extract(?1, '$.thread_id') WHERE a = json_extract(?1, '$.topic_id')";
pub(super) const RENAME_RELATIONS_B: &str = "UPDATE OR IGNORE relations SET b = json_extract(?1, '$.thread_id') WHERE b = json_extract(?1, '$.topic_id')";
pub(super) const RENAME_RELATIONS_DROP: &str = "DELETE FROM relations WHERE (a = json_extract(?1, '$.topic_id') OR b = json_extract(?1, '$.topic_id')) AND json_extract(?1, '$.topic_id') <> json_extract(?1, '$.thread_id')";
pub(super) const RENAME_TOPIC: &str = "INSERT INTO topics (id, label, probability, thread_id, until_ms, until_key, thread_at_ms, created_at_ms, last_at_ms, state, urgency, reach, score, verdict, closed_at_ms, previous) SELECT json_extract(?1, '$.thread_id'), label, probability, thread_id, until_ms, until_key, thread_at_ms, created_at_ms, last_at_ms, state, urgency, reach, score, verdict, closed_at_ms, previous FROM topics WHERE id = json_extract(?1, '$.topic_id') AND id <> json_extract(?1, '$.thread_id')";
pub(super) const REOPEN: &str = "UPDATE topics SET state = 'open', closed_at_ms = 0 WHERE state = 'archived' AND id IN (SELECT topic_id FROM members WHERE created_at_ms = json_extract(?1, '$.at_ms') AND key IN (SELECT value FROM json_each(?1, '$.live')))";
pub(super) const RESCORE: &str = "UPDATE topics SET score = urgency + (1 - urgency) * MIN(json_extract(?1, '$.reach.cap'), json_extract(?1, '$.reach.people') * MAX(json_extract(reach, '$.people') - 1, 0) + json_extract(?1, '$.reach.conversations') * MAX(json_extract(reach, '$.conversations') - 1, 0) + json_extract(?1, '$.reach.sources') * MAX(json_extract(reach, '$.sources') - 1, 0)) WHERE id IN (SELECT topic_id FROM members WHERE created_at_ms = json_extract(?1, '$.at_ms'))";
pub(super) const RESTATE: &str = "UPDATE lines SET text = json_extract(?1, '$.text'), rules_rev = json_extract(?1, '$.rev'), updated_at_ms = json_extract(?1, '$.at_ms') WHERE key = json_extract(?1, '$.key') AND state IN ('queued', 'screening')";
pub(super) const REVIEWS: &str = "SELECT json_group_array(json_object('left', side, 'right', other, 'tag', json(tag))) FROM (SELECT side, other, tag FROM (SELECT COALESCE((SELECT x.text FROM members d JOIN lines x ON x.key = d.key WHERE d.topic_id = p.a AND x.state = 'approved' ORDER BY x.occurred_at_ms, x.key LIMIT 1), (SELECT label FROM topics WHERE id = p.a), '') AS side, COALESCE((SELECT x.text FROM members d JOIN lines x ON x.key = d.key WHERE d.topic_id = p.b AND x.state = 'approved' ORDER BY x.occurred_at_ms, x.key LIMIT 1), (SELECT label FROM topics WHERE id = p.b), '') AS other, json_object('a', p.a, 'b', p.b, 'no', 'unlike', 'yes', 'maybe') AS tag, 0 AS rank, p.a AS first, p.b AS second FROM relations p WHERE p.kind = 'maybe' AND p.count < json_extract(?1, '$.merge_after') AND p.a <> p.b AND EXISTS (SELECT 1 FROM topics WHERE id = p.a) AND EXISTS (SELECT 1 FROM topics WHERE id = p.b) UNION ALL SELECT l.text, COALESCE((SELECT x.text FROM members d JOIN lines x ON x.key = d.key WHERE d.topic_id = m.topic_id AND x.state = 'approved' ORDER BY x.occurred_at_ms, x.key LIMIT 1), (SELECT label FROM topics WHERE id = m.topic_id), ''), json_object('a', m.key, 'b', m.topic_id, 'no', 'apart', 'yes', 'kept'), 1, m.key, m.topic_id FROM members m JOIN lines l ON l.key = m.key WHERE m.via = 'choice' AND l.state = 'approved' AND NOT EXISTS (SELECT 1 FROM members e JOIN lines f ON f.key = e.key WHERE e.topic_id = m.topic_id AND e.via = 'choice' AND f.conversation_id = l.conversation_id AND (f.occurred_at_ms, f.key) < (l.occurred_at_ms, l.key)) AND NOT EXISTS (SELECT 1 FROM relations r WHERE r.a = m.key AND r.b = m.topic_id AND r.kind = 'kept') AND COALESCE((SELECT r.count FROM relations r WHERE r.a = m.key AND r.b = m.topic_id AND r.kind = 'apart'), 0) < json_extract(?1, '$.split_after')) ORDER BY rank, first, second LIMIT json_extract(?1, '$.limit'))";
pub(super) const REVIVE: &str = concat!(
    "UPDATE batches SET state = 'ready', revivals = revivals + 1, reason = '', updated_at_ms = 0 WHERE id = (SELECT id FROM batches WHERE state = 'failed' AND revivals >= 0 AND revivals < json_extract(?1, '$.max_revivals') AND ",
    due!("updated_at_ms", "revivals + 1"),
    " ORDER BY id LIMIT 1) AND NOT EXISTS (SELECT 1 FROM batches WHERE state = 'ready')"
);
pub(super) const ROLLBACK: &str = "ROLLBACK";
pub(super) const RULES: &str = "SELECT json_group_array(json_object('id', id, 'pattern', pattern, 'placeholder', placeholder)) FROM (SELECT * FROM learned_rules WHERE id > json_extract(?1, '$.after') ORDER BY id)";
pub(super) const SCREENED: &str = "UPDATE lines SET text = json_extract(?1, '$.text'), flag = json_extract(?1, '$.flag'), hints = json_extract(?1, '$.hints'), state = json_extract(?1, '$.state'), reason = json_extract(?1, '$.reason'), reviewer = json_extract(?1, '$.reviewer'), updated_at_ms = json_extract(?1, '$.at_ms') WHERE key = json_extract(?1, '$.key') AND state = 'screening'";
pub(super) const SCREENING: &str = concat!(
    "SELECT json_group_array(json_object('attempts', attempts, 'key', key, 'text', text)) FROM (SELECT attempts, key, text FROM lines WHERE state = 'screening' AND batch_id > 0 AND (reason = '' OR ",
    due!("updated_at_ms", "attempts"),
    ") ORDER BY occurred_at_ms, key LIMIT json_extract(?1, '$.limit'))"
);
pub(super) const SEALABLE: &str = "SELECT json_group_array(json_object('batch_id', batch_id)) FROM (SELECT DISTINCT l.batch_id AS batch_id FROM lines l WHERE l.batch_id > json_extract(?1, '$.after') AND NOT EXISTS (SELECT 1 FROM batches b WHERE b.id = l.batch_id) AND NOT EXISTS (SELECT 1 FROM lines p WHERE p.batch_id = l.batch_id AND p.state = 'screening') AND (NOT EXISTS (SELECT 1 FROM batches o WHERE o.state NOT IN ('sent', 'failed')) OR NOT EXISTS (SELECT 1 FROM lines a WHERE a.batch_id = l.batch_id AND a.state = 'approved')) ORDER BY l.batch_id LIMIT 1)";
pub(super) static SETTLE: [&str; 18] = [
    CHANGE_DROP,
    CHANGE_CLAIM,
    SETTLE_TOPIC,
    SETTLE_SHIFT,
    SETTLE_LEAVE,
    SETTLE_RETIME,
    SETTLE_ALIAS_CHAIN,
    SETTLE_ALIAS,
    SETTLE_ALERTS_MERGED,
    SETTLE_ALERTS,
    SETTLE_CALLS,
    SETTLE_RELATIONS_A,
    SETTLE_RELATIONS_B,
    SETTLE_RELATIONS_DROP,
    SETTLE_DELETE,
    SETTLE_REACH,
    SETTLE_RESCORE,
    SETTLE_ALERT,
];
const SETTLE_ALERT: &str = "INSERT OR IGNORE INTO alerts (key, topic_id, state, attempts, analysis, reason, created_at_ms, updated_at_ms, score, origin) SELECT t.id || '@c' || json_extract(?1, '$.id'), t.id, 'waiting', 0, NULL, '', json_extract(?1, '$.at_ms'), 0, t.score, json_extract(?1, '$.kind') FROM topics t WHERE t.id IN (json_extract(?1, '$.from'), json_extract(?1, '$.to')) AND (t.score >= json_extract(?1, '$.threshold') OR t.thread_id <> '') AND t.last_at_ms >= json_extract(?1, '$.since_ms') AND NOT EXISTS (SELECT 1 FROM alerts o WHERE o.topic_id = t.id AND o.state IN ('waiting', 'pending') AND o.analysis IS NULL AND o.attempts = 0) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_ALERTS: &str = "UPDATE alerts SET topic_id = json_extract(?1, '$.to') WHERE topic_id = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_ALERTS_MERGED: &str = "UPDATE alerts SET state = 'merged', merged_into = json_extract(?1, '$.to') WHERE topic_id = json_extract(?1, '$.from') AND state IN ('waiting', 'pending', 'analyzed') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_ALIAS: &str = "INSERT OR REPLACE INTO topic_aliases (old, new) SELECT json_extract(?1, '$.from'), json_extract(?1, '$.to') WHERE json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_ALIAS_CHAIN: &str = "UPDATE topic_aliases SET new = json_extract(?1, '$.to') WHERE new = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
pub(super) const SETTLE_CALL: &str = "UPDATE calls SET state = json_extract(?1, '$.state'), total_input = json_extract(?1, '$.input_tokens'), total_output = json_extract(?1, '$.output_tokens'), input_tokens = MAX(json_extract(?1, '$.input_tokens') - COALESCE((SELECT p.total_input FROM calls p WHERE json_extract(?1, '$.resumed') AND p.kind = calls.kind AND p.topic_id = calls.topic_id AND p.state = 'success' AND p.at_ms < calls.at_ms ORDER BY p.at_ms DESC LIMIT 1), 0), 0), output_tokens = MAX(json_extract(?1, '$.output_tokens') - COALESCE((SELECT p.total_output FROM calls p WHERE json_extract(?1, '$.resumed') AND p.kind = calls.kind AND p.topic_id = calls.topic_id AND p.state = 'success' AND p.at_ms < calls.at_ms ORDER BY p.at_ms DESC LIMIT 1), 0), 0) WHERE kind = json_extract(?1, '$.kind') AND subject = json_extract(?1, '$.subject') AND attempt = json_extract(?1, '$.attempt')";
const SETTLE_CALLS: &str = "UPDATE calls SET topic_id = json_extract(?1, '$.to') WHERE topic_id = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_DELETE: &str = "DELETE FROM topics WHERE id = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_LEAVE: &str = "DELETE FROM members WHERE topic_id = json_extract(?1, '$.from') AND (json_extract(?1, '$.kind') = 'merge' OR key IN (SELECT value FROM json_each(?1, '$.keys'))) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_REACH: &str = "UPDATE topics SET urgency = (SELECT m.probability FROM members m JOIN lines l ON l.key = m.key WHERE m.topic_id = topics.id AND m.probability IS NOT NULL ORDER BY l.occurred_at_ms DESC, l.key DESC LIMIT 1), reach = (SELECT json_object('conversations', COUNT(DISTINCT CASE WHEN copy THEN NULL ELSE conversation_id END), 'people', COUNT(DISTINCT CASE WHEN copy THEN NULL ELSE person END), 'sources', COUNT(DISTINCT source)) FROM (SELECT l.conversation_id AS conversation_id, g.source AS source, CASE WHEN l.role = '' AND l.state <> 'withheld' THEN COALESCE(i.person_id, g.source || ':' || g.sender_id, l.sender) END AS person, l.digest <> '' AND EXISTS (SELECT 1 FROM members d JOIN lines e ON e.key = d.key WHERE d.topic_id = m.topic_id AND e.digest = l.digest AND (e.occurred_at_ms, e.key) < (l.occurred_at_ms, l.key)) AS copy FROM members m JOIN lines l ON l.key = m.key LEFT JOIN messages g ON g.key = m.key LEFT JOIN identities i ON i.source = g.source AND i.sender_id = g.sender_id WHERE m.topic_id = topics.id)) WHERE id IN (json_extract(?1, '$.from'), json_extract(?1, '$.to')) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_RELATIONS_A: &str = "UPDATE OR IGNORE relations SET a = json_extract(?1, '$.to') WHERE a = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_RELATIONS_B: &str = "UPDATE OR IGNORE relations SET b = json_extract(?1, '$.to') WHERE b = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'merge' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_RELATIONS_DROP: &str = "DELETE FROM relations WHERE ((json_extract(?1, '$.kind') = 'merge' AND (a = json_extract(?1, '$.from') OR b = json_extract(?1, '$.from') OR a = b)) OR (json_extract(?1, '$.kind') = 'split' AND b = json_extract(?1, '$.from') AND kind IN ('apart', 'kept') AND a IN (SELECT value FROM json_each(?1, '$.keys')))) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
pub(super) const SETTLE_REMINDER: &str = "UPDATE reminders SET state = json_extract(?1, '$.state'), updated_at_ms = json_extract(?1, '$.at_ms') WHERE key = json_extract(?1, '$.key')";
const SETTLE_RESCORE: &str = "UPDATE topics SET score = urgency + (1 - urgency) * MIN(json_extract(?1, '$.reach.cap'), json_extract(?1, '$.reach.people') * MAX(json_extract(reach, '$.people') - 1, 0) + json_extract(?1, '$.reach.conversations') * MAX(json_extract(reach, '$.conversations') - 1, 0) + json_extract(?1, '$.reach.sources') * MAX(json_extract(reach, '$.sources') - 1, 0)) WHERE id IN (json_extract(?1, '$.from'), json_extract(?1, '$.to')) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_RETIME: &str = "UPDATE topics SET last_at_ms = COALESCE((SELECT MAX(l.occurred_at_ms) FROM members m JOIN lines l ON l.key = m.key WHERE m.topic_id = topics.id), last_at_ms), state = CASE WHEN id = json_extract(?1, '$.to') THEN 'open' ELSE state END, closed_at_ms = CASE WHEN id = json_extract(?1, '$.to') THEN 0 ELSE closed_at_ms END, thread_at_ms = CASE WHEN id = json_extract(?1, '$.from') THEN 0 ELSE thread_at_ms END WHERE id IN (json_extract(?1, '$.from'), json_extract(?1, '$.to')) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_SHIFT: &str = "INSERT OR IGNORE INTO members (key, topic_id, probability, batch_id, via, created_at_ms) SELECT key, json_extract(?1, '$.to'), probability, batch_id, CASE WHEN json_extract(?1, '$.kind') = 'merge' THEN via ELSE json_extract(?1, '$.kind') END, json_extract(?1, '$.at_ms') FROM members WHERE topic_id = json_extract(?1, '$.from') AND (json_extract(?1, '$.kind') = 'merge' OR key IN (SELECT value FROM json_each(?1, '$.keys'))) AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
const SETTLE_TOPIC: &str = "INSERT OR IGNORE INTO topics (id, label, probability, thread_id, until_ms, until_key, thread_at_ms, created_at_ms, last_at_ms) SELECT json_extract(?1, '$.to'), label, NULL, '', 0, '', 0, json_extract(?1, '$.at_ms'), last_at_ms FROM topics WHERE id = json_extract(?1, '$.from') AND json_extract(?1, '$.kind') = 'split' AND EXISTS (SELECT 1 FROM changes g WHERE g.id = json_extract(?1, '$.id') AND g.state = 'applied' AND g.at_ms = json_extract(?1, '$.at_ms'))";
pub(super) const STALE: &str = "SELECT json_group_array(json_object('key', key, 'text', text)) FROM (SELECT key, text FROM lines WHERE state IN ('queued', 'screening') AND rules_rev < json_extract(?1, '$.rev') ORDER BY state = 'queued', occurred_at_ms DESC, key DESC LIMIT json_extract(?1, '$.limit'))";
pub(super) const STRANGERS: &str = "SELECT json_group_array(json_object('name', name, 'sender_id', sender_id, 'source', source)) FROM (SELECT source, sender_id, sender_name AS name, MAX(occurred_at_ms) FROM messages GROUP BY source, sender_id) WHERE json_extract(?1, '$') IS NULL AND EXISTS (SELECT 1 FROM messages m WHERE NOT EXISTS (SELECT 1 FROM identities i WHERE i.source = m.source AND i.sender_id = m.sender_id))";
pub(super) const STUCK: &str = "SELECT json_group_array(json_object('batch_id', batch_id, 'reason', reason)) FROM (SELECT batch_id, reason FROM (SELECT l.batch_id AS batch_id, 'screening' AS reason FROM lines l WHERE l.batch_id > json_extract(?1, '$.after') AND l.state = 'screening' AND NOT EXISTS (SELECT 1 FROM batches b WHERE b.id = l.batch_id) UNION ALL SELECT id, 'sending' FROM batches WHERE state = 'ready') ORDER BY batch_id LIMIT 1)";
pub(super) const STUDIED: &str = "UPDATE topics SET digest = json_extract(?1, '$.digest') WHERE id = json_extract(?1, '$.topic_id')";
pub(super) const SUPERSEDED: &str = "SELECT json_group_array(1) FROM (SELECT 1 WHERE EXISTS (SELECT 1 FROM changes c WHERE c.state = 'pending' AND (c.from_topic = json_extract(?1, '$.topic_id') OR c.to_topic = json_extract(?1, '$.topic_id'))) OR EXISTS (SELECT 1 FROM alerts n WHERE n.topic_id = json_extract(?1, '$.topic_id') AND (n.created_at_ms, n.key) > (json_extract(?1, '$.created_at_ms'), json_extract(?1, '$.key')) AND n.state IN ('waiting', 'pending') AND n.analysis IS NULL))";
pub(super) const SUSPECT: &str = concat!(
    "INSERT OR IGNORE INTO relations (a, b, kind, count) SELECT p.later, p.earlier, k.kind, k.count FROM (SELECT DISTINCT ma.topic_id AS later, mb.topic_id AS earlier FROM clues ca JOIN clues cb ON cb.kind = ca.kind AND cb.value = ca.value AND cb.key <> ca.key JOIN members ma ON ma.key = ca.key JOIN members mb ON mb.key = cb.key JOIN topics ta ON ta.id = ma.topic_id JOIN topics tb ON tb.id = mb.topic_id WHERE ca.kind NOT IN ('digest', 'mail', 'seen') AND ma.topic_id <> mb.topic_id AND (ta.created_at_ms, ta.id) > (tb.created_at_ms, tb.id) AND ",
    sparse!("ca"),
    ") p JOIN (SELECT 'clued' AS kind, 1 AS count UNION ALL SELECT 'maybe', 0) k WHERE NOT EXISTS (SELECT 1 FROM relations r WHERE r.a = p.later AND r.b = p.earlier AND r.kind = 'clued')"
);
pub(super) const TOPICS: &str = "INSERT INTO topics (id, label, probability, thread_id, until_ms, until_key, thread_at_ms, created_at_ms, last_at_ms) SELECT COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(value, '$.topic')), json_extract(value, '$.topic')), json_extract(value, '$.label'), json_extract(value, '$.probability'), '', 0, '', 0, json_extract(?1, '$.at_ms'), json_extract(value, '$.last_ms') FROM json_each(?1, '$.topics') WHERE true ON CONFLICT(id) DO UPDATE SET probability = NULLIF(MAX(COALESCE(topics.probability, -1), COALESCE(excluded.probability, -1)), -1), last_at_ms = MAX(topics.last_at_ms, excluded.last_at_ms)";
pub(super) const TOPIC_LINES: &str = "SELECT json_group_array(json_object('digest', digest, 'key', key, 'occurred_at_ms', occurred_at_ms, 'omitted', omitted, 'role', role, 'sender', sender, 'source', source, 'text', text)) FROM (SELECT l.digest AS digest, l.key AS key, l.occurred_at_ms AS occurred_at_ms, CASE WHEN l.state = 'withheld' THEN l.reason WHEN COALESCE(g.purged_at_ms, 0) > 0 THEN 'purged' END AS omitted, l.role AS role, CASE WHEN l.state = 'withheld' OR COALESCE(g.purged_at_ms, 0) > 0 THEN '' ELSE l.sender END AS sender, g.source AS source, CASE WHEN l.state = 'withheld' OR COALESCE(g.purged_at_ms, 0) > 0 THEN '' ELSE l.text END AS text FROM members p JOIN lines l ON l.key = p.key LEFT JOIN messages g ON g.key = l.key WHERE p.topic_id = json_extract(?1, '$.topic_id') AND l.state IN ('approved', 'withheld') ORDER BY l.occurred_at_ms, l.key)";
pub(super) const UNINDEXED: &str = "SELECT json_group_array(json_object('key', key, 'occurred_at_ms', occurred_at_ms, 'raw', json(raw), 'text', text)) FROM (SELECT m.key AS key, m.occurred_at_ms AS occurred_at_ms, CASE WHEN json_valid(m.raw) THEN m.raw ELSE 'null' END AS raw, m.text AS text FROM lines l JOIN messages m ON m.key = l.key WHERE l.state <> 'skipped' AND NOT EXISTS (SELECT 1 FROM clues c WHERE c.kind = 'seen' AND c.value = l.key) ORDER BY l.occurred_at_ms DESC, l.key DESC LIMIT json_extract(?1, '$.limit'))";
pub(super) const UNLIKE: &str = "DELETE FROM relations WHERE kind IN ('maybe', 'unlike') AND EXISTS (SELECT 1 FROM relations u WHERE u.a = relations.a AND u.b = relations.b AND u.kind = 'unlike' AND u.count >= json_extract(?1, '$.merge_after'))";
pub(super) const UNLINED: &str = "SELECT json_group_array(json_object('account', account, 'bulk', bulk, 'conversation_id', conversation_id, 'key', key, 'occurred_at_ms', occurred_at_ms, 'sender_id', sender_id, 'sender_name', sender_name, 'source', source, 'text', text)) FROM (SELECT m.account AS account, CASE WHEN json_valid(m.raw) THEN json_extract(m.raw, '$.bulk') END AS bulk, m.conversation_id AS conversation_id, m.key AS key, m.occurred_at_ms AS occurred_at_ms, m.sender_id AS sender_id, m.sender_name AS sender_name, m.source AS source, m.text AS text FROM messages m WHERE m.occurred_at_ms >= json_extract(?1, '$.since_ms') AND NOT EXISTS (SELECT 1 FROM lines l WHERE l.key = m.key) ORDER BY m.occurred_at_ms DESC, m.key DESC LIMIT json_extract(?1, '$.limit'))";
pub(super) const UNRELATED: &str = "UPDATE lines SET state = 'unrelated', reason = 'no_topic', updated_at_ms = json_extract(?1, '$.at_ms') WHERE state = 'approved' AND key IN (SELECT json_extract(value, '$.key') FROM json_each(?1, '$.placements') WHERE json_extract(value, '$.topic') IS NULL)";
pub(super) const VERDICT: &str = "UPDATE topics SET digest = '', version = json_extract(?1, '$.version'), state = json_extract(?1, '$.status'), closed_at_ms = CASE WHEN json_extract(?1, '$.status') = 'open' THEN 0 ELSE json_extract(?1, '$.at_ms') END, label = CASE WHEN json_extract(?1, '$.title') <> '' THEN json_extract(?1, '$.title') ELSE label END, verdict = json_extract(?1, '$.analysis') WHERE id = json_extract(?1, '$.thread_id')";
pub(super) const VOTE: &str = "INSERT INTO relations (a, b, kind, count) SELECT COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(value, '$.tag.a')), json_extract(value, '$.tag.a')), COALESCE((SELECT new FROM topic_aliases WHERE old = json_extract(value, '$.tag.b')), json_extract(value, '$.tag.b')), CASE WHEN json_extract(value, '$.probability') >= json_extract(?1, '$.review_threshold') THEN json_extract(value, '$.tag.yes') ELSE json_extract(value, '$.tag.no') END, 1 FROM json_each(?1, '$.reviews') WHERE json_extract(value, '$.probability') IS NOT NULL ON CONFLICT(a, b, kind) DO UPDATE SET count = count + 1";
pub(super) const WAKE_ALERTS: &str = "UPDATE alerts SET state = 'pending', updated_at_ms = 0 WHERE state = 'waiting' AND json_extract(?1, '$') IS NULL";
